import {AppError,choice} from '@crew/shared';
import {Readable} from 'node:stream';
import {pipeline} from 'node:stream/promises';
import {getIssue,publicLabel} from '../work/issues.js';
import {listComments} from '../work/comments.js';
import {publicRelation} from '../work/relations.js';
import {publicProject} from '../work/projects.js';
export const TRANSFER_FORMAT='crew.project';
export const TRANSFER_VERSION=1;
export function exportProject(ctx,req,projectId) {
  const row=ctx.permissions.assertProject(req,projectId,'export:read');
  const project=publicProject(ctx.db,row);
  const issues=ctx.db.prepare('SELECT id FROM issues WHERE project_id=? ORDER BY number,id').all(projectId).map(row=>getIssue(ctx,row.id));
  const issueIds=new Set(issues.map(issue=>issue.id));
  const comments=issues.flatMap(issue=>listComments(ctx,issue.id));
  const external=new Map();
  const relations=ctx.db.prepare(`SELECT DISTINCT r.* FROM issue_relations r JOIN issues i
    ON i.id=r.source_issue_id OR i.id=r.target_issue_id WHERE i.project_id=? ORDER BY r.created_at,r.id`).all(projectId)
    .filter(relation=>{
      for(const id of [relation.source_issue_id,relation.target_issue_id]){
        const issue=getIssue(ctx,id);
        if(!ctx.permissions.canProject(req.user.id,issue.projectId,'project:read'))return false;
      }
      return true;
    }).map(row=>{
      const relation=publicRelation(ctx,row);
      for(const id of [relation.sourceIssueId,relation.targetIssueId])if(!issueIds.has(id)){
        const item=getIssue(ctx,id);external.set(id,{id:item.id,key:item.key,title:item.title,projectId:item.projectId});
      }
      return {id:relation.id,sourceIssueId:relation.sourceIssueId,targetIssueId:relation.targetIssueId,kind:relation.kind,createdBy:relation.createdBy,createdAt:relation.createdAt};
    });
  const userIds=new Set();
  for(const issue of issues){userIds.add(issue.createdBy);if(issue.assigneeId)userIds.add(issue.assigneeId);}
  for(const comment of comments)userIds.add(comment.authorId);
  for(const relation of relations)userIds.add(relation.createdBy);
  const users=[...userIds].map(id=>ctx.db.prepare('SELECT id,name,email FROM users WHERE id=?').get(id));
  return {format:TRANSFER_FORMAT,version:TRANSFER_VERSION,exportedAt:ctx.now(),
    project:{id:project.id,key:project.key,name:project.name,description:project.description},
    statuses:project.statuses.map(({id,name,category,position})=>({id,name,category,position})),
    users,externalIssues:[...external.values()],
    labels:ctx.db.prepare('SELECT * FROM labels WHERE project_id=? ORDER BY name,id').all(projectId).map(publicLabel)
      .map(({id,name,color,createdAt,updatedAt})=>({id,name,color,createdAt,updatedAt})),
    issues:issues.map(issue=>({id:issue.id,number:issue.number,title:issue.title,description:issue.description,statusId:issue.statusId,
      priority:issue.priority,assigneeId:issue.assigneeId,estimate:issue.estimate,dueDate:issue.dueDate,parentId:issue.parentId,
      createdBy:issue.createdBy,rank:issue.rank,labelIds:issue.labels.map(label=>label.id),createdAt:issue.createdAt,updatedAt:issue.updatedAt})),
    comments:comments.map(({id,issueId,authorId,body,createdAt,updatedAt})=>({id,issueId,authorId,body,createdAt,updatedAt})),relations};
}
export function csvCell(value) {
  let text=value===null||value===undefined?'':String(value);
  if(/^[\s]*[=+@-]/.test(text))text="'"+text;
  return '"'+text.replaceAll('"','""')+'"';
}
export function* csvChunks(document) {
  const columns=['number','title','description','status','priority','assignee','estimate','dueDate','parentNumber','labels','createdAt','updatedAt'];
  yield columns.map(csvCell).join(',')+'\r\n';
  const statuses=new Map(document.statuses.map(item=>[item.id,item.name]));
  const users=new Map(document.users.map(item=>[item.id,item.email]));
  const labels=new Map(document.labels.map(item=>[item.id,item.name]));
  const numbers=new Map(document.issues.map(item=>[item.id,item.number]));
  for(const issue of document.issues) {
    const values={...issue,status:statuses.get(issue.statusId),assignee:users.get(issue.assigneeId)??'',
      parentNumber:numbers.get(issue.parentId)??'',labels:issue.labelIds.map(id=>labels.get(id)).join('; ')};
    yield columns.map(column=>csvCell(values[column])).join(',')+'\r\n';
  }
}
export function* jsonChunks(document) {
  yield '{';
  let first=true;
  for(const [key,value] of Object.entries(document)) {
    if(!first)yield ',';first=false;
    yield JSON.stringify(key)+':';
    if(!Array.isArray(value)){yield JSON.stringify(value);continue;}
    yield '[';let firstItem=true;
    for(const item of value){if(!firstItem)yield ',';firstItem=false;yield JSON.stringify(item);}
    yield ']';
  }
  yield '}\n';
}
export async function sendExport(ctx,req,res) {
  const format=choice(req.query.format,'format',['json','csv'],'json');
  const document=exportProject(ctx,req,req.params.projectId);
  const filename=document.project.key.toLowerCase()+'-project.'+format;
  res.set({'Content-Type':format==='csv'?'text/csv; charset=utf-8':'application/json; charset=utf-8',
    'Content-Disposition':'attachment; filename="'+filename+'"','Cache-Control':'private, no-store'});
  try{await pipeline(Readable.from(format==='csv'?csvChunks(document):jsonChunks(document)),res);}
  catch(error){if(!res.destroyed)throw error;}
}
